UPDATE public.b2b_managed_products SET
  model_name = 'Kompakt-Modell 12 kg/24 h, Bullet-Eis – ideal für Bar, Hausbar & Feiern',
  description = 'Kompakte Eiswürfelmaschine mit bis zu 12 kg Eis pro Tag. Vollautomatisch, mit 3,2-l-Wassertank – kein Wasseranschluss nötig. Erste Eiswürfel nach wenigen Minuten.',
  detailed_description = 'Kompakter SLT Eiswürfelbereiter zum Mieten – die praktische Eiswürfelmaschine für Hochzeiten, Firmenfeiern, Gartenpartys, Foodtrucks, Messestände und den privaten Haushalt. Das freistehende Edelstahl-Tischgerät produziert bis zu 12 kg Bullet-Eis pro 24 Stunden – 14 Eiskugeln pro Zyklus – vollautomatisch aus dem integrierten 3,2-Liter-Wassertank, ohne festen Wasseranschluss. So lässt es sich flexibel überall dort aufstellen, wo Strom vorhanden ist – auf der Theke, im Cateringzelt oder im Getränkeausschank.

Die Bedienung erfolgt über ein Touch-Bedienfeld mit LED-Display: Wasser einfüllen, Eisgröße wählen, starten – nach wenigen Minuten sind die ersten Eiswürfel fertig. Ein Alarmsignal meldet vollen Eisbehälter oder niedrigen Wasserstand. Der leistungsstarke, geräuscharme Kompressor arbeitet mit dem Kältemittel R290 und produziert ohne Vorkühlzeit durchgehend. Das Sichtfenster im Deckel zeigt jederzeit den Füllstand, der entnehmbare Vorratsbehälter (1,8 kg) erleichtert Entnahme, Umfüllen in einen Getränkekühler und Reinigung.

Das Gerät ist an unserem Hauptsitz Krefeld und an unserer Filiale Bonn direkt buchbar. Für Mülheim an der Ruhr disponieren wir es kurzfristig aus dem Hauptsitz Krefeld.',
  images = ARRAY['/product-images/geschirr/slt-eiswuerfelbereiter-1.jpeg','/product-images/geschirr/slt-eiswuerfelbereiter-2.jpeg','/product-images/geschirr/slt-eiswuerfelbereiter-3.jpeg'],
  image_alts = ARRAY['SLT Eiswürfelbereiter kompakt mieten – Edelstahl-Eiswürfelmaschine mit Sichtfenster','SLT Eiswürfelbereiter kompakt – Abmessungen 31 x 43 x 40 cm','Entnehmbarer Eisvorratsbehälter mit Bullet-Eis und Eisschaufel'],
  specifications = '{"Geräteart":"Freistehende Eiswürfelmaschine (Ice Maker), Tischgerät","Eisproduktion":"ca. 12 kg / 24 h, 14 Eiskugeln pro Zyklus (Bullet-Eis)","Wassertank":"3,2 Liter, manuelles Nachfüllen","Eisvorratsbehälter":"1,8 kg, entnehmbar","Gehäuse":"Edelstahl, Silber – Deckel mit Sichtfenster","Abmessungen (B×H×T)":"ca. 31 × 43 × 40 cm","Gewicht":"ca. 12,5 kg","Stromversorgung":"220–240 V~ / 50–60 Hz (Schuko-Steckdose)","Kältemittel":"R290","Bedienung":"Touch-Bedienfeld mit LED-Display, Alarm bei vollem Behälter / niedrigem Wasserstand","Netzkabel":"ca. 130 cm","Aufstellort":"Bar-/Küchentheke, Cateringzelt, Foodtruck, Büro, Hausbar"}'::jsonb,
